B='49地道奇人.txt'
make('qiyi_xiansheng','奇异先生',B,
'奇异先生是一位失明的男子，从达华拉宫地下群体中逃出后，被外界误认为狼童。他熟悉的是没有昼夜之分、以老鼠为食、替皇帝看守财富的地道生活，所以描述逃亡路程时，只能说吃完十七只老鼠便到达红巴，无法给出现代地图上的里程。他后来受齐密教授等人照料，学习英语与外面的生活知识，仍始终坚持自己并非野兽养大的孩子。教授去世后，他靠异常敏锐的听觉和感觉在街头及夜总会表演谋生，逢人讲述故乡，却被当作幻想或笑话。他找木兰花，不是为了占有宝藏，而是想让仍困在地下的族人获得别样生活，甚至愿拿出全部积蓄组织探险。绑匪以枪威胁时，他故意说不认识木兰花，以免牵连来救自己的人；敏锐听觉也及时发现楼上还藏着敌人。但突然的机枪声反而使他受惊失措，在被撞倒保护后又站起来逃向门口，遭洛丁尼射杀。后来探险证实地下确有长期生活的群体，却只剩约二十五年前死亡的遗骨，死因未明。他没有亲眼见到这个结果，终局综合参战可知道调查结论，但不能凭失明或听觉获得灵魂视野、全知导航或使族人复活的力量。',
'遭洛丁尼机枪射杀；其故乡和地道群体后来被证实存在，族人已死，原因未明。','异常敏锐的听觉与环境感觉','能凭脚步辨人、听见他人未察觉的细微移动，在熟悉环境中定位；曾靠此表演谋生。','完全失明，不能从听觉得到未发声的完整图像；巨响会干扰判断，旧地理记忆不等于现代坐标。',[(28,74,'听觉与感觉表现。'),(96,176,'地下出身、外界教育与救助族人的愿望。'),(1520,1658,'保护来客、预警与被射杀。'),(2544,2556,'地道遗骨年代及未知死因。')],
'使别人相信故乡与族人确实存在，并帮助他们离开长期黑暗的生活。',[('自己的经历被当作笑话','仍希望族人获救','继续解释并寻找愿意调查的人。'),('罪犯逼问援助者身份','担忧牵连对方','宁愿冒险否认认识。'),('突然强烈枪声袭来','敏锐听觉被冲击且无法目视局势','可能受惊误判，需同伴明确引导而非自动避弹。')],scores=(1,0,1,2,2,2),tier='并',dead=True)
make('gongmu','宫木大佐',B,
'宫木是旧日军第七通信兵团副司令，在缅北丛林与部下隔绝生活二十多年。他仍用旧军阶和服从要求控制小泽、太仓，保存残余武器，花多年绘制周围详细地图，也掌握通往达华拉宫的路线。初遇木兰花时，他以军人身份威胁她，难以接受战争已经结束；作为通信军官，面对现代收音机的结构仍感困惑，这种知识断代使他不能等同于现代全能工程专家。木兰花给他的收音机确实让他获知战败事实，然而信息没有自动带来放下武力。他从广播中读出强权仍能侵略的逻辑，转而宣布脱离旧皇军，要把宫殿珠宝变卖，购买军火、招募士兵，从丛林建立自己的帝国。他以仅存手榴弹逼木兰花参加或死，仍高度警觉，不肯让她轻易接近。木兰花指出旧弹延时的限制，在他投弹时冲近制击；爆炸震塌石柱，惊出大量蛇群，宫木最终遭蛇缠咬而死。他的远征帝国始终只是计划，不能给终局卡配上从未建成的军队。人物的危险来自把挫败不断转译为新扩张理由，而不是单纯不知道历史。',
'投弹引发废宫蛇群逃窜，遭蛇缠咬死亡；新帝国计划未实现。','旧军训练与丛林测绘','具军事纪律、通信背景、详细本地地图与长期野外生存经验，能使用保存的手榴弹。','技术知识与现代脱节，弹药有限；没有建成军队，身体不能抵抗蛇缠咬或爆炸。',[(700,806,'身份、旧军逻辑与收音机。'),(936,982,'地图、空枪和四枚手榴弹。'),(1240,1322,'接受战败却另谋帝国，投弹。'),(1392,1414,'死亡确认。')],
'拒绝承认自己多年服从与等待毫无意义，试图把军事权威重新变成领土与统治。',[('新证据证明旧战争结束','原有忠诚失去对象','可能接受事实却另造扩张目标。'),('部下脱离命令','担忧仅有的权威瓦解','追踪并以剩余武器恢复服从。'),('有人否定建国计划','仍相信暴力决定合法性','要求加入或消灭对方，容易忽略旧武器的限制。')],roles=('反派',),scores=(3,0,1,3,3,3),tier='并',dead=True)
for key,name,detail,death,deathref in [
 ('oze_yoshimoto','小泽吉源','他说明野草极快遮住旧路，并指出宫木多年绘制地图，比两个士兵更熟悉地形。','被蛇缠住头颈，在树旁窒息死亡。',(1394,1398)),
 ('taicang_yilang','太仓一郎','他提醒同伴黎明前毒雾会升起，展示树上的路线记号，并说出宫木仍藏四枚手榴弹。','被大蛇把头部与石块缠压，头部严重损毁死亡。',(1400,1402))]:
 make(key,name,B,
 f'{name}是与宫木一起留在缅北丛林二十多年的旧日军士兵，原文给出姓名，但未给出足够材料把他写成独立的高级军官。他与另一名士兵熟悉林间路线、休息方法、干粮与军刀开路，子弹早已用尽，仍维持旧军队的称呼和对上司的恐惧。木兰花制住宫木后，告诉他们战争已经过去、可以回到家人与国家身边，两人一度愿意带路，问起日本近况时流露出真实向往。然而听说宫木只是暂时昏迷，并可能追来，旧有威慑立刻压过新生活的吸引力。他们甚至想返回请求原谅，对木兰花的保证也缺乏信心。{detail} 这些表现说明他确有多年积累的地方经验，不能仅当作毫无判断的傀儡；但经验没有自动转化为摆脱权威的勇气。后来两人在途中背离木兰花，再站回宫木一边。宫木投弹导致蛇群冲出，三名士兵全部死亡。{death} 终局参战应保留对旧服从的依赖、对外界的好奇和已失败的选择，不把日本军阶当成超能力，不补写未曾回乡的幸福结局，也不默认有已经耗尽的枪弹。',
 death,'丛林生存与军刀开路','凭长期驻留掌握路线标记、避开低处毒雾、寻找树上休息点，以常磨军刀砍开植被。','地方经验不等于全世界生存知识；惧怕宫木，步枪缺弹，不能抵御蛇群。',[(868,876,'姓名和同意带路。'),(912,1004,'经验、用刀、地图与对宫木的恐惧。'),(1414,1420,'途中背离与死亡总结。'),(*deathref,'个人死亡状态。')],
 '渴望离开长期孤立的生活，却深受旧上司惩罚的恐惧牵制。',[('有人承诺战争已结束','暂时相信上司不能再惩罚','愿合作带路并询问家乡变化。'),('得知宫木可能追来','多年服从恐惧重现','摇摆甚至回到上司一边。'),('进入熟悉丛林险地','尚有时间准备','使用树上避雾、记号与军刀等实际经验。')],roles=('阶段性对立者',),scores=(2,0,1,2,2,2),tier='并',dead=True)
make('luodingni','洛丁尼',B,
'洛丁尼是意大利夜总会主人，明说单靠正常营业无法发财。他听奇异先生讲达华拉宫时，没有像旁人那样只是嘲笑，而是花了近半年追查其经历，发现当年破旧鼠皮衣上缀着宝石，由此把一段不被相信的生命故事读成了获利机会。他带手下来逼盲人返回故乡，自己躲在楼上听完木兰花已经发现宫殿的谈话，随后以机枪出现，杀死受惊奔逃的奇异先生，并迫使木兰花作向导。他能够识破木兰花临时声称宫殿只是幻想的搪塞，也知道她与黑手党交锋的名声，因而既畏惧又想控制她。绑架远行中，他需要向导知识，却从未把这种需要变成真正信任。林间夜宿时，主角戴防毒面具脱入浓雾，他立刻认定所谓毒雾只是骗局，命手下一起追下树去。毒性确实存在，他随即剧烈咳嗽、要求爬回高处，终于被自己拒绝相信的环境条件击败。救援者留下另一辆车，丹警官判断他若及时返回可治疗并依法追究，否则可能死于森林。文本没有确认最终获救或死亡，不可把推测写成既成结局，更不能给他宫殿宝藏的所有权。',
'与手下落入有毒浓雾，呼吸系统可能严重受损；是否及时返镇治疗及最终判决未写明。','犯罪经营与宝藏调查','能追查旧资料、组织武装绑架和远行，用机枪及信息优势控制向导。','需要本地向导与防护；贪欲和不信任会压过环境警告，不能抵抗毒雾。',[(1630,1664,'机枪袭击杀死奇异先生。'),(1692,1760,'夜总会身份、半年调查及绑架。'),(2348,2382,'追入毒雾与条件性结局。')],
'把他人身世线索转化为私人财富，排除阻止自己取得宝藏的人。',[('人人嘲笑的故事含实物线索','发现宝石等获利证据','投入调查并秘密跟踪。'),('向导拒绝合作','已掌握部分路线信息','以枪和已知线索施压，降低其谈判筹码。'),('被控制者脱逃','先入为主认定自己受骗','仓促否定警告追击，可能遭真实环境反噬。')],roles=('反派',),scores=(3,0,1,3,3,3),tier='并')
for key,name,detail in [('hande','汉德','他是夜总会总管，押住奇异先生，以枪指其后脑，逼问木兰花身份，随后在退上楼梯时被麻醉针击倒。'),('kaluo','卡罗','他属于先在花园中被木兰花麻醉制住的同伙，姓名由首领点问、其他手下确认，正文没有给他独立的职业履历。')]:
 make(key,name,B,
 f'{name}是洛丁尼手下参与达华拉宫夺宝绑架的成员。{detail} 这次行动并非保护正常夜总会生意，而是对无法提供现代路线坐标的失明者施压，要从他的故乡故事中取得宝藏。木兰花突入后，前场数名歹徒或中麻醉、或逃出花园，首领却隐藏在楼上，靠机枪重新夺取控制。{name}不是重新出现便能免疫麻醉的人，他在昏迷后由同伙用冷水弄醒，还经历头晕和不明情况的阶段，约十分钟才清醒。之后洛丁尼集合六人押木兰花远行，首领明确期待找到数不清的财富。林中看守者被主角反制后，众人或跌入、或追入毒雾，整个六人小组都陷于危险；原文未逐一说明他是看守中的哪一个，也没有给出他最终在医疗站获救或被捕的独立画面。因此人物卡保留实际的执行身份、受制经验和依附首领的行动边界，不把洛丁尼的半年调查、杀死奇异先生的开枪或每项枪法自动复制到他身上。终局仍是小组败逃、可能严重吸入毒雾的状态，不能凭空补上完好无损的资源。',
 '所属六人绑架组在毒雾中失败；个人最终治疗与司法结果未详述。','绑架执行与武器威慑','参与看守、胁迫及转移，依照首领命令合作；有被麻醉后恢复的普通生理过程。','未证明特别武技；可被麻醉，毒雾危险需防具，个人最后位置不能由群体倒推。',[(1520,1568,'绑架现场与成员被麻醉。'),(1752,1760,'姓名、被淋醒与出发命令。'),(2352,2382,'六人组失败和未定结局。')],
 '追随首领以绑架换取财富，优先服从掌握武装与计划的人。',[('目标不肯提供路线','首领要求尽快取证','参与恐吓和看守而非耐心验证身世。'),('强敌已经控制现场','个人处于明显劣势','可能被制或退避，等待首领重新取得优势。'),('首领要求继续追击','缺少独立防护与环境判断','跟随行动并承担相同的毒雾风险。')],roles=('反派',),scores=(2,0,1,2,1,2),tier='并')
